import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';

const Signup = () => {
  const navigate = useNavigate();
  const { signup } = useAuth();
  
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    confirmPassword: '',
    gender: 'neutral' // Default to neutral
  });
  
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate password match
    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }
    
    setIsLoading(true);
    setError('');

    try {
      // In a real app, this would create user via API
      await new Promise(resolve => setTimeout(resolve, 800)); // Simulate API call
      
      // Simple validation for demo
      if (formData.name && formData.email && formData.password) {
        const result = signup({
          name: formData.name,
          email: formData.email,
          gender: formData.gender, // Include gender in signup data
          // In a real app, never store raw passwords in state or localStorage
        });
        
        if (result.success) {
          navigate('/onboarding');
        }
      } else {
        setError('Please fill out all fields');
      }
    } catch (err) {
      setError('An error occurred during signup. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="relative flex flex-col items-center justify-center min-h-screen p-4 overflow-hidden bg-neural-dark">
      {/* Neural background effect */}
      <div className="absolute inset-0 neural-network-bg">
        {Array.from({ length: 15 }).map((_, i) => (
          <motion.circle
            key={i}
            r={Math.random() * 3 + 1}
            fill="rgba(100, 200, 255, 0.3)"
            cx={`${Math.random() * 100}%`}
            cy={`${Math.random() * 100}%`}
            initial={{ opacity: 0.1 }}
            animate={{ 
              opacity: [0.1, 0.3, 0.1],
              scale: [1, 1.2, 1],
            }}
            transition={{ 
              duration: Math.random() * 3 + 2,
              repeat: Infinity,
              delay: Math.random() * 2,
            }}
          />
        ))}
      </div>

      {/* Connection lines */}
      <svg className="absolute inset-0 w-full h-full neural-connection">
        {Array.from({ length: 10 }).map((_, i) => (
          <motion.path
            key={i}
            stroke="rgba(100, 200, 255, 0.15)"
            strokeWidth="1"
            fill="none"
            d={`M${Math.random() * 100},${Math.random() * 100} C${Math.random() * 100},${Math.random() * 100} ${Math.random() * 100},${Math.random() * 100} ${Math.random() * 100},${Math.random() * 100}`}
            initial={{ pathLength: 0, opacity: 0 }}
            animate={{ 
              pathLength: 1, 
              opacity: [0, 0.3, 0]
            }}
            transition={{ 
              duration: Math.random() * 4 + 3,
              repeat: Infinity,
              delay: Math.random() * 2
            }}
          />
        ))}
      </svg>

      {/* Signup card */}
      <motion.div 
        className="neural-card w-full max-w-md p-6 z-10"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.6 }}
      >
        <div className="text-center mb-8">
          <motion.h1 
            className="text-3xl font-bold neural-text-gradient"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.2, duration: 0.8 }}
          >
            Track Your Study
          </motion.h1>
          <motion.p 
            className="mt-2 text-white/70"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3, duration: 0.8 }}
          >
            Create a new account
          </motion.p>
        </div>

        {error && (
          <motion.div 
            className="mb-4 p-3 bg-red-900/40 border border-red-500/30 rounded-lg text-red-300 text-sm"
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
          >
            {error}
          </motion.div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="mb-4">
            <label htmlFor="name" className="block mb-2 text-sm font-medium text-white/80">
              Full Name
            </label>
            <input
              type="text"
              id="name"
              name="name"
              className="neural-input w-full text-white/90"
              placeholder="Enter your full name"
              value={formData.name}
              onChange={handleChange}
              required
            />
          </div>

          <div className="mb-4">
            <label htmlFor="email" className="block mb-2 text-sm font-medium text-white/80">
              Email
            </label>
            <input
              type="email"
              id="email"
              name="email"
              className="neural-input w-full text-white/90"
              placeholder="Enter your email"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </div>
          
          {/* Gender selection with avatar preview */}
          <div className="mb-4">
            <label className="block mb-2 text-sm font-medium text-white/80">
              Gender (for avatar)
            </label>
            <div className="grid grid-cols-3 gap-4 mb-4">
              {/* Gender options */}
              <div 
                className={`flex flex-col items-center cursor-pointer p-3 rounded-lg transition-all ${formData.gender === 'male' ? 'bg-blue-500/20 border border-blue-500/50' : 'bg-neural-800/40 hover:bg-neural-800/60'}`}
                onClick={() => handleChange({ target: { name: 'gender', value: 'male' } })}
              >
                <svg width="40" height="40" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="50" cy="50" r="50" fill="#4F46E5" />
                  <circle cx="50" cy="50" r="35" fill="#E5E7EB" />
                  <circle cx="35" cy="45" r="5" fill="#1F2937" />
                  <circle cx="65" cy="45" r="5" fill="#1F2937" />
                  <path d="M35,65 Q50,75 65,65" stroke="#1F2937" strokeWidth="3" fill="none" />
                </svg>
                <span className="mt-2 text-sm text-white/80">Male</span>
              </div>
              
              <div 
                className={`flex flex-col items-center cursor-pointer p-3 rounded-lg transition-all ${formData.gender === 'female' ? 'bg-pink-500/20 border border-pink-500/50' : 'bg-neural-800/40 hover:bg-neural-800/60'}`}
                onClick={() => handleChange({ target: { name: 'gender', value: 'female' } })}
              >
                <svg width="40" height="40" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="50" cy="50" r="50" fill="#EC4899" />
                  <circle cx="50" cy="50" r="35" fill="#FCE7F3" />
                  <circle cx="35" cy="45" r="5" fill="#1F2937" />
                  <circle cx="65" cy="45" r="5" fill="#1F2937" />
                  <path d="M35,65 Q50,75 65,65" stroke="#1F2937" strokeWidth="3" fill="none" />
                </svg>
                <span className="mt-2 text-sm text-white/80">Female</span>
              </div>
              
              <div 
                className={`flex flex-col items-center cursor-pointer p-3 rounded-lg transition-all ${formData.gender === 'neutral' ? 'bg-green-500/20 border border-green-500/50' : 'bg-neural-800/40 hover:bg-neural-800/60'}`}
                onClick={() => handleChange({ target: { name: 'gender', value: 'neutral' } })}
              >
                <svg width="40" height="40" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg">
                  <circle cx="50" cy="50" r="50" fill="#10B981" />
                  <circle cx="50" cy="50" r="35" fill="#D1FAE5" />
                  <circle cx="35" cy="45" r="5" fill="#1F2937" />
                  <circle cx="65" cy="45" r="5" fill="#1F2937" />
                  <rect x="40" y="65" width="20" height="6" rx="3" fill="#1F2937" />
                </svg>
                <span className="mt-2 text-sm text-white/80">Neutral</span>
              </div>
            </div>
          </div>

          <div className="mb-4">
            <label htmlFor="password" className="block mb-2 text-sm font-medium text-white/80">
              Password
            </label>
            <input
              type="password"
              id="password"
              name="password"
              className="neural-input w-full text-white/90"
              placeholder="Create a password"
              value={formData.password}
              onChange={handleChange}
              required
              minLength="8"
            />
            <p className="mt-1 text-xs text-white/50">
              Password must be at least 8 characters
            </p>
          </div>

          <div className="mb-6">
            <label htmlFor="confirmPassword" className="block mb-2 text-sm font-medium text-white/80">
              Confirm Password
            </label>
            <input
              type="password"
              id="confirmPassword"
              name="confirmPassword"
              className="neural-input w-full text-white/90"
              placeholder="Confirm your password"
              value={formData.confirmPassword}
              onChange={handleChange}
              required
            />
          </div>

          <motion.button
            type="submit"
            className="neural-button w-full py-3 rounded-lg bg-dendrite-primary/20 border border-dendrite-base text-white font-medium"
            whileHover={{ scale: 1.02, boxShadow: '0 0 15px rgba(100, 200, 255, 0.5)' }}
            whileTap={{ scale: 0.98 }}
            disabled={isLoading}
          >
            {isLoading ? (
              <span className="flex items-center justify-center">
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Creating account...
              </span>
            ) : (
              'Sign Up'
            )}
          </motion.button>
        </form>

        <div className="mt-6 text-center">
          <p className="text-white/60 text-sm">
            Already have an account?{' '}
            <Link to="/login" className="text-neural-primary hover:text-neural-secondary transition-colors">
              Log in
            </Link>
          </p>
        </div>
      </motion.div>
    </div>
  );
};

export default Signup; 